import os
os.environ.setdefault("PYTORCH_ENABLE_MPS_FALLBACK", "1")

import cv2
import numpy as np

try:
    import torch
except Exception:
    torch = None


def select_torch_device(preference="auto"):
    preference = str(preference or "auto").lower()
    if torch is not None:
        if preference in {"cuda", "auto"}:
            try:
                if torch.cuda.is_available():
                    return "cuda"
            except Exception:
                pass
        if preference in {"mps", "auto"}:
            try:
                if torch.backends.mps.is_available():
                    return "mps"
            except Exception:
                pass
    return "cpu"


def ros_image_to_bgr(img):
    data = img.get("data") or []
    fmt = str(img.get("format") or "").lower()
    if fmt or not img.get("height"):
        arr = np.frombuffer(data, dtype=np.uint8)
        if arr.size <= 0:
            return None
        return cv2.imdecode(arr, cv2.IMREAD_COLOR)
    h = int(img.get("height") or 0)
    w = int(img.get("width") or 0)
    enc = str(img.get("encoding") or "rgb8").lower()
    if h <= 0 or w <= 0:
        return None
    channels = 1 if enc == "mono8" else (4 if enc in {"rgba8", "bgra8"} else 3)
    arr = np.frombuffer(data, dtype=np.uint8)
    needed = h * w * channels
    if arr.size < needed:
        return None
    arr = arr[:needed].reshape((h, w, channels))
    if enc == "rgb8":
        return cv2.cvtColor(arr, cv2.COLOR_RGB2BGR)
    if enc == "rgba8":
        return cv2.cvtColor(arr, cv2.COLOR_RGBA2BGR)
    if enc == "bgra8":
        return cv2.cvtColor(arr, cv2.COLOR_BGRA2BGR)
    if enc == "mono8":
        return cv2.cvtColor(arr, cv2.COLOR_GRAY2BGR)
    return arr.copy()


def bgr_to_ros_image(bgr):
    if bgr is None:
        return None
    if len(bgr.shape) == 2:
        rgb = cv2.cvtColor(bgr, cv2.COLOR_GRAY2RGB)
    else:
        rgb = cv2.cvtColor(bgr, cv2.COLOR_BGR2RGB)
    rgb = np.ascontiguousarray(rgb, dtype=np.uint8)
    h, w = rgb.shape[:2]
    return {
        "height": int(h),
        "width": int(w),
        "encoding": "rgb8",
        "is_bigendian": 0,
        "step": int(w * 3),
        "data": rgb.tobytes(),
    }from PIL import Image
from transformers import pipeline


def depth_anything_overlay(state, img, params):
    bgr = ros_image_to_bgr(img)
    if bgr is None:
        return None
    model_id = params.get("model") or "depth-anything/Depth-Anything-V2-Small-hf"
    preference = params.get("devicePreference") or "auto"
    device = select_torch_device(preference)
    key = "pipeline:" + model_id + ":" + device
    pipe = state.get(key)
    if pipe is None:
        device_index = 0 if device == "cuda" else -1
        pipe = pipeline("depth-estimation", model=model_id, device=device_index)
        state[key] = pipe
        print("Depth Anything device:", device)
    rgb = cv2.cvtColor(bgr, cv2.COLOR_BGR2RGB)
    result = pipe(Image.fromarray(rgb))
    depth = np.array(result["depth"])
    depth = cv2.resize(depth, (bgr.shape[1], bgr.shape[0]))
    depth = cv2.normalize(depth, None, 0, 255, cv2.NORM_MINMAX).astype(np.uint8)
    color = cv2.applyColorMap(depth, cv2.COLORMAP_INFERNO)
    alpha = float(params.get("alpha", 0.55) or 0.55)
    out = cv2.addWeighted(bgr, 1.0 - alpha, color, alpha, 0)
    return bgr_to_ros_image(out)
